head.script:
scwin.checkEl = function() {
    if (WebSquare.wUnit.getJq("#wq_uuid_5").length > 0) {
        return WebSquare.wUnit.getJq("#wq_uuid_5").attr("type") == "text" && WebSquare.wUnit.getJq("#wq_uuid_5")[0].nodeName == "INPUT";
    } else {
        return WebSquare.wUnit.getJq("#wq_uuid_1_wq_uuid_5").attr("type") == "text" && WebSquare.wUnit.getJq("#wq_uuid_1_wq_uuid_5")[0].nodeName == "INPUT";
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행하여 tabControl안에 inputbox가 보이는지 확인한다.
    //1. Run the sample file to make sure the input box is visible in the tabControl.
    //Verify 1. tabControl안에 inputbox가 정상적으로 보여진다.(이전에는 보이지 않음)
    //1. The input box is displayed normally in the tabControl (not shown previously).                
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl() ", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 27-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
